/// <summary>
/// Extension of GUPItemBasePriceCalcJob
/// </summary>
[ExtensionOf(classStr(GUPItemBasePriceCalcJob))]
internal final class METGUPItemBasePriceCalcJobCls_Extension
{
    private NoYes   generatePriceChangeInquiry;
    private NoYes   includeClaimFromVendor;

}

Method.Source:
/// <summary>
/// Pack
/// </summary>
/// <returns>container value</returns>
public container pack()
{
    return SysPackExtensions::appendExtension(next pack(), classStr(METGUPItemBasePriceCalcJobCls_Extension), [generatePriceChangeInquiry, includeClaimFromVendor]);
}

    /// <summary>
    /// Unpack
    /// </summary>
    /// <param name = "_pack">pack</param>
    /// <returns>boolean value</returns>
    public boolean unpack(container _pack)
    {
        boolean ret = next unpack(_pack);

        if (ret)
        {
            container extensionState = SysPackExtensions::findExtension(_pack, classStr(METGUPItemBasePriceCalcJobCls_Extension));

            generatePriceChangeInquiry = conPeek(extensionState, 1);
            includeClaimFromVendor  = conPeek(extensionState, 2);
        }

        return ret;
    }

/// <summary>
/// Include claim from vendor parm
/// </summary>
/// <param name = "_includeClaimFromVendor">Include claim from vendor</param>
/// <returns>NoYesvalue</returns>
public NoYes parmMETIncludeClaimFromVendor(NoYes _includeClaimFromVendor = includeClaimFromVendor)
{
    includeClaimFromVendor = _includeClaimFromVendor;
    return includeClaimFromVendor;
}

/// <summary>
/// run method
/// </summary>
public void run()
{
    next run();
    if (this.parmMETIncludeClaimFromVendor())
    {
        METVendClaimProcessJob::contructMETVendClaimProcessTasks(this.parmCalcDate(), this.parmSiteId(), this);
    }
}
